(gen_random_uuid(),'MULTIPLE_CHOICE',9,'GRAMMAR_PUNCTUATION','Rhetorical Devices',5,NULL,NULL,'PREMIUM','HARD',
'Which sentence uses antithesis?','{"A":"Not all those who wander are lost.","B":"To err is human; to forgive, divine.","C":"The roaring of the waves echoed endlessly.","D":"She had a heart of gold."}','{"value":"B"}','Antithesis contrasts opposing ideas in parallel structure: "to err is human" vs "to forgive, divine".','PUBLISHED',NOW(),NULL),
(gen_random_uuid(),'MULTIPLE_CHOICE',9,'GRAMMAR_PUNCTUATION','Clauses',5,NULL,NULL,'PREMIUM','HARD',
'In "Whatever decision the committee reaches will affect the entire organisation", what is the function of "Whatever decision the committee reaches"?','{"A":"Adjectival clause","B":"Adverbial clause","C":"Noun clause acting as subject","D":"Relative clause"}','{"value":"C"}','The entire clause "Whatever decision the committee reaches" functions as the subject of the verb "will affect".','PUBLISHED',NOW(),NULL),
(gen_random_uuid(),'MULTIPLE_CHOICE',9,'GRAMMAR_PUNCTUATION','Punctuation',5,NULL,NULL,'PREMIUM','HARD',
'Which sentence correctly punctuates a direct quote within an academic essay?','{"A":"Smith (2020) argued that \"the evidence is unequivocal\" (p. 45).","B":"Smith (2020) argued that, the evidence is unequivocal (p. 45).","C":"Smith (2020) argued that the evidence is ''unequivocal'' (p. 45).","D":"Smith (2020) argued: \"the evidence is unequivocal\". (p. 45)"}','{"value":"A"}','Academic citation requires quotation marks around the exact words, with page reference in brackets after.','PUBLISHED',NOW(),NULL),
